#include <cstdio>
#include <cctype>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

typedef pair<int, int> coord;

const int INF_VAL = 1000000000;
const int MAX_SIZE = 11;
const int MAX_NODES = 205;
const int DIRECTIONS_COUNT = 4;
const int delta_y[DIRECTIONS_COUNT] = {-1, 0, 1, 0};
const int delta_x[DIRECTIONS_COUNT] = {0, -1, 0, 1};

int size_n, max_t;
char grid[MAX_SIZE][MAX_SIZE], backup[MAX_SIZE][MAX_SIZE];
int start_r, start_c;
int dist_bum[MAX_SIZE][MAX_SIZE];
int dist_map[MAX_SIZE][MAX_SIZE];
bool reach[MAX_SIZE][MAX_SIZE];
int total_vertices;
int cap[MAX_SIZE][MAX_SIZE];
vector<int> adj_list[MAX_NODES];
int flow_arr[MAX_NODES], parent_arr[MAX_NODES];

void first_bfs()
{
    fill((int*)cap, (int*)cap + MAX_SIZE * MAX_SIZE, max_t);
    cap[start_r][start_c] = 0;
    queue<coord> q; q.push(coord(start_r, start_c));
    while (!q.empty()) {
        coord v = q.front(); int d = cap[v.first][v.second]; q.pop();
        for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
            coord u = coord(v.first + delta_y[dir], v.second + delta_x[dir]);
            if (0 <= u.first && u.first < size_n && 0 <= u.second && u.second < size_n && grid[u.first][u.second] != 'Y' && d + 1 < cap[u.first][u.second])
                cap[u.first][u.second] = d + 1, q.push(u);
        }
    }
}

void second_bfs(int sr, int sc)
{
    fill((int*)dist_map, (int*)dist_map + MAX_SIZE * MAX_SIZE, INF_VAL);
    dist_map[sr][sc] = 0;
    fill((bool*)reach, (bool*)reach + MAX_SIZE * MAX_SIZE, false);
    reach[sr][sc] = true;
    queue<coord> q; q.push(coord(sr, sc));
    while (!q.empty()) {
        coord v = q.front(); int d = dist_map[v.first][v.second]; q.pop();
        reach[v.first][v.second] = d <= cap[v.first][v.second];
        if (d >= cap[v.first][v.second]) continue;
        for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
            coord u = coord(v.first + delta_y[dir], v.second + delta_x[dir]);
            if (0 <= u.first && u.first < size_n && 0 <= u.second && u.second < size_n && grid[u.first][u.second] != 'Y' && d + 1 < dist_map[u.first][u.second])
                dist_map[u.first][u.second] = d + 1, q.push(u);
        }
    }
}

void run_bfs(int sr, int sc, int d[][MAX_SIZE], int INF_VAL)
{
    fill((int*)d, (int*)d + MAX_SIZE * MAX_SIZE, INF_VAL);
    d[sr][sc] = 0;
    queue<coord> q; q.push(coord(sr, sc));
    while (!q.empty()) {
        coord v = q.front(); int d_v = d[v.first][v.second]; q.pop();
        for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
            coord u = coord(v.first + delta_y[dir], v.second + delta_x[dir]);
            if (0 <= u.first && u.first < size_n && 0 <= u.second && u.second < size_n && grid[u.first][u.second] != 'Y' && d_v + 1 < d[u.first][u.second])
                d[u.first][u.second] = d_v + 1, q.push(u);
        }
    }
}

int max_flow()
{
    fill(flow_arr, flow_arr + total_vertices, 0); flow_arr[0] = INF_VAL;
    priority_queue<coord> pq; pq.push(coord(INF_VAL, 0));
    while (!pq.empty()) {
        int v = pq.top().second, f = pq.top().first; pq.pop();
        if (flow_arr[v] != f) continue;
        for (size_t i = 0; i < adj_list[v].size(); i++) {
            int u = adj_list[v][i];
            if (min(f, cap[v][u]) > flow_arr[u]) flow_arr[u] = min(f, cap[v][u]), parent_arr[u] = v, pq.push(coord(flow_arr[u], u));
        }
    }
    int v = total_vertices - 1;
    if (flow_arr[v] == 0) return 0;
    int total_flow = flow_arr[v];
    while (v != 0) {
        int u = parent_arr[v];
        cap[u][v] -= total_flow; cap[v][u] += total_flow;
        v = u;
    }
    return total_flow;
}

int main()
{
    scanf("%d %d", &size_n, &max_t);
    for (int i = 0; i < size_n; i++)
        for (int j = 0; j < size_n; j++) {
            scanf(" %c", &grid[i][j]);
            if (grid[i][j] == 'Z') { start_r = i; start_c = j; }
        }
    for (int i = 0; i < size_n; i++)
        for (int j = 0; j < size_n; j++)
            scanf(" %c", &backup[i][j]);
    first_bfs();
    total_vertices = 2 * size_n * size_n + 2;
    for (int i = 0; i < size_n; i++)
        for (int j = 0; j < size_n; j++) if (isdigit(grid[i][j]) && grid[i][j] > '0') {
            int v = i * size_n + j + 1; cap[0][v] = grid[i][j] - '0'; adj_list[0].push_back(v); adj_list[v].push_back(0);
            second_bfs(i, j);
            for (int i2 = 0; i2 < size_n; i2++)
                for (int j2 = 0; j2 < size_n; j2++) if (reach[i2][j2] && isdigit(backup[i2][j2]) && backup[i2][j2] > '0') {
                    int u = size_n * size_n + i2 * size_n + j2 + 1; cap[v][u] = MAX_INF; adj_list[v].push_back(u); adj_list[u].push_back(v);
                }
        }
    for (int i = 0; i < size_n; i++)
        for (int j = 0; j < size_n; j++) if (isdigit(backup[i][j]) && backup[i][j] > '0') {
            int u = size_n * size_n + i * size_n + j + 1; cap[u][total_vertices - 1] = backup[i][j] - '0'; adj_list[u].push_back(total_vertices - 1); adj_list[total_vertices - 1].push_back(u);
        }
    int flow;
    int total_flow_value = 0;
    while ((flow = max_flow()) != 0) total_flow_value += flow;
    printf("%d\n", total_flow_value);
    return 0;
}
